  "ringkas": "IHSG anjlok 3,64 persen pada Senin, memicu gelombang buyback oleh emiten-emiten besar, sementara tiga nama yang ikut dalam gelombang itu, Barito Renewables, Petrindo Jaya Kreasi, dan Dian Swastatika Sentosa, justru sedang menjawab sorotan OJK soal transaksi sahamnya sendiri.",
